{
  "name": "magpie-google-aistudio",
  "version": "0.2.1",
  "description": "Google AI Studio provider plugin for Magpie (official API key, multi-key pool, thought_signature cache, Nano Banana images, Gemini 3.8 TTS, Gemini 3.5 Transcribe)",
  "type": "module",
  "main": "./index.mjs",
  "exports": {
    ".": "./index.mjs",
    "./core": "./src/core.mjs"
  },
  "files": [
    "index.mjs",
    "src/",
    "README.md",
    "LICENSE"
  ],
  "keywords": [
    "magpie",
    "magpie-plugin",
    "opencode",
    "opencode-plugin",
    "provider",
    "gemini",
    "google-ai-studio"
  ],
  "author": "qq136692547-cmyk",
  "homepage": "https://github.com/qq136692547-cmyk/magpie-google-aistudio#readme",
  "bugs": {
    "url": "https://github.com/qq136692547-cmyk/magpie-google-aistudio/issues"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/qq136692547-cmyk/magpie-google-aistudio.git"
  },
  "license": "MIT",
  "engines": {
    "node": ">=20"
  },
  "scripts": {
    "test": "node --test index.test.mjs",
    "test:live": "node test-live.mjs"
  },
  "magpie": {
    "name": "Google AI Studio",
    "icon": "data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24'><path fill='%234285F4' d='M12 2c.6 5.2 4.8 9.4 10 10-5.2.6-9.4 4.8-10 10-.6-5.2-4.8-9.4-10-10 5.2-.6 9.4-4.8 10-10z'/></svg>",
    "maxConcurrency": 6,
    "summary": {
      "en": "Google AI Studio API Key provider with multi-key failover, thought_signature cache, Nano Banana 2.1, Gemini 3.8 TTS and 3.5 Transcribe.",
      "zh": "Google AI Studio 官方 API Key 插件：支持多 Key 轮询防限流、思考签名自动补全、Nano Banana 生图改图、TTS 与语音转录。"
    }
  }
}
